/* Links do porquê, Odontologia Legal (Rafael 25/11/2026): afirmação que precisa de explicação.
   t = trecho exato do texto do site; p = o motivo jurídico/ético (com artigo e número); fonte = a norma ou o estudo. */
(function(){ var B = window.BANCOS && window.BANCOS.legal; if (!B) return;
  var L5081 = 'Lei 5.081/1966 (exercício da Odontologia), https://www.planalto.gov.br/ccivil_03/leis/l5081.htm';
  var L12030 = 'Lei 12.030/2009 (perícias oficiais), https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2009/lei/l12030.htm';
  var L6710 = 'Lei 6.710/1979 (técnico em prótese dentária), https://www.planalto.gov.br/ccivil_03/leis/l6710.htm';
  var L4324 = 'Lei 4.324/1964 (cria o CFO e os CROs), https://www.planalto.gov.br/ccivil_03/leis/l4324.htm';
  var CPP = 'Código de Processo Penal (Decreto-Lei 3.689/1941), https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm';
  var CP = 'Código Penal (Decreto-Lei 2.848/1940), https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm';
  var CC = 'Código Civil (Lei 10.406/2002), https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm';
  var CDC = 'Código de Defesa do Consumidor (Lei 8.078/1990), https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm';
  var CF = 'Constituição Federal de 1988, https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm';
  var CEO = 'Código de Ética Odontológica, Res. CFO-118/2012 (em vigor desde 01/01/2013), https://website.cfo.org.br/wp-content/uploads/2018/03/codigo_etica.pdf';
  var R196 = 'Res. CFO-196, de 29/01/2019, https://sistemas.cfo.org.br/visualizar/atos/RESOLU%C3%87%C3%83O/SEC/2019/196';
  var R271 = 'Res. CFO-271, de 18/06/2025, https://sistemas.cfo.org.br/visualizar/atos/RESOLU%C3%87%C3%83O/SEC/2025/271';
  var L13787 = 'Lei 13.787/2018 (prontuário digitalizado), https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13787.htm';
  var LGPD = 'LGPD (Lei 13.709/2018), https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm';
  var ECA = 'Estatuto da Criança e do Adolescente (Lei 8.069/1990), https://www.planalto.gov.br/ccivil_03/leis/l8069.htm';
  var INT = 'INTERPOL, ficha "Disaster victim identification" (2023), https://www.interpol.int/content/download/621/file/FS-02-DVI-2023-03-EN.pdf';
  var MAL = 'Malik SD e cols., J Oral Maxillofac Pathol 2022 (revisão), PMID 37082063, https://pmc.ncbi.nlm.nih.gov/articles/PMC10112107/';
  var NIST = 'NIST, Bitemark Analysis: A NIST Scientific Foundation Review, NISTIR 8352 (07/03/2023), https://doi.org/10.6028/NIST.IR.8352';
  var VAN = 'Vanrell JP, Odontologia Legal e Antropologia Forense (Guanabara Koogan)';
  var PIN = 'Pinheiro A e cols., Morphologie 2023, PMID 37149420, https://doi.org/10.1016/j.morpho.2023.04.001';
  var MOR = 'Moraes ME e cols., Braz Oral Res 2007, PMID 17710293, https://doi.org/10.1590/s1806-83242007000300012';
  var DEM = 'Demirjian A, Goldstein H, Tanner JM, A new system of dental age assessment, Human Biology 1973; 45(2): 211-227';
  var STJ = 'STJ, notícia de 16/07/2026, REsp 2.225.449 (Terceira Turma), https://www.stj.jus.br/sites/portalp/Paginas/Comunicacao/Noticias/2026/16072026-Paciente-que-obteve-restituicao-por-erro-em-cirurgia-odontologica-nao-pode-exigir-custeio-de-nova-operacao.aspx';
  var AGM = 'Agência Minas (Governo de MG), 24/01/2023, https://www.agenciaminas.mg.gov.br/noticia/governo-segue-mobilizado-para-levar-alento-a-familiares-das-vitimas-de-brumadinho-115826';
  var MPRJ = 'MPRJ, notícia de 20/02/2022, https://www.mprj.mp.br/web/guest/visualizar?noticiaId=111408';
  var SBT = 'SBT News, 15/08/2024, IML conclui identificação das 62 vítimas do voo 2283, https://sbtnews.sbt.com.br/noticia/brasil/queda-de-aviao-iml-conclui-identificacao-das-62-vitimas-do-acidente-aereo-em-vinhedo-sp';
  var INO = 'Innocence Project, caso de 1991 em Phoenix (Arizona), https://innocenceproject.org/cases/ray-krone/';
  var ECK = 'Eckert WG, Teixeira WR, Am J Forensic Med Pathol 1985, PMID 3916651, https://pubmed.ncbi.nlm.nih.gov/3916651/';
  var JEF = 'Jeffreys AJ e cols., Forensic Sci Int 1992, PMID 1398379, https://pubmed.ncbi.nlm.nih.gov/1398379/';
  var a = function (base, art) { return art ? base + ', ' + art : base; };
  B.porques = (B.porques || []).concat([

  /* ---------- Conceito e perícia ---------- */
  { t: "A perícia não é exclusiva do médico", p: "Porque a Lei 5.081/1966, no art. 6º, IV, dá ao cirurgião-dentista a competência para a perícia odontolegal em todos os foros (civil, criminal, trabalhista e administrativo). Quem melhor entende de dente, osso da face e tratamento odontológico é o dentista; o médico-legista examina o resto do corpo, e os dois podem trabalhar juntos. Ex.: num processo trabalhista em Petrópolis sobre perda de dentes num acidente na fábrica, o juiz nomeia um odontolegista como perito, e o laudo dele vale como prova.", fonte: a(L5081, 'art. 6º, IV') },
  { t: "atua também no vivo", p: "Porque a lei manda o dentista fazer perícia nos foros civil, criminal, trabalhista e administrativo (Lei 5.081, art. 6º, IV), e quase todos esses casos envolvem pessoas vivas: lesão corporal no rosto, estimativa de idade de quem não tem documento, erro de tratamento, atestado falso. O cadáver e a ossada são só uma parte do trabalho. Ex.: a vítima de uma agressão que perdeu dois dentes passa por exame de corpo de delito com o odontolegista do IML, para o laudo dizer se a lesão foi leve ou grave.", fonte: a(L5081, 'art. 6º, IV') },
  { t: "peritos médico-legistas e peritos odontolegistas", p: "Porque o art. 5º da Lei 12.030/2009 lista expressamente as três carreiras de perito oficial de natureza criminal, e o odontolegista está nela com o mesmo status do médico-legista. A lei reconhece que identificação pelos dentes, lesões na boca e marcas na face exigem formação própria. Ex.: no IML, o laudo de identificação de uma vítima carbonizada, feito pela comparação do odontograma com o prontuário, é assinado pelo perito odontolegista.", fonte: a(L12030, 'art. 5º') },
  { t: "com formação superior específica", p: "Porque o perito oficial precisa dominar a área do que examina: o laudo só tem valor se quem o assinou tem conhecimento técnico para chegar àquela conclusão. Por isso a Lei 12.030/2009 (art. 5º) exige formação superior específica, detalhada em regulamento por área. Ex.: para examinar fratura de mandíbula e perda de dentes numa vítima de agressão, o perito odontolegista precisa ser cirurgião-dentista.", fonte: a(L12030, 'art. 5º') },
  { t: "Duas pessoas idôneas, com diploma de curso superior", p: "Porque, sem o perito oficial, a lei compensa a falta de concurso e de vínculo com o Estado colocando DOIS examinadores, que conferem um ao outro, e exige diploma superior para garantir preparo técnico (CPP, art. 159, §1º). Eles ainda prestam compromisso de desempenhar o encargo com fidelidade (§2º), o que os responsabiliza pelo laudo. Ex.: numa cidade pequena sem IML, o delegado nomeia dois cirurgiões-dentistas da cidade para examinar a boca de uma vítima de agressão.", fonte: a(CPP, 'art. 159, §§1º e 2º') },
  { t: "preferencialmente na área do exame", p: "Porque o exame de corpo de delito precisa de quem entenda do que está olhando: um dentista descreve melhor uma fratura dental ou uma luxação do que um engenheiro, mesmo os dois tendo diploma superior. O CPP pede 'preferencialmente na área específica' (art. 159, §1º) para que o laudo seja tecnicamente confiável. Ex.: para a perícia de dentes quebrados numa briga, o delegado sem perito oficial chama dois cirurgiões-dentistas, e não dois advogados.", fonte: a(CPP, 'art. 159, §1º') },
  { t: "de preferência da área", p: "Porque o valor do laudo depende de o perito entender do assunto. Na falta do perito oficial, o CPP (art. 159, §1º) pede que as duas pessoas idôneas tenham diploma superior preferencialmente na área do exame, com habilitação técnica ligada à natureza da perícia. Ex.: para examinar a boca de uma criança que perdeu dentes numa agressão, o ideal é nomear dois cirurgiões-dentistas, que sabem distinguir dente decíduo de permanente e trauma de cárie.", fonte: a(CPP, 'art. 159, §1º') },
  { t: "a confissão não supre o exame de corpo de delito", p: "Porque a confissão pode ser falsa: alguém pode confessar para proteger outra pessoa, por medo ou sob pressão. Quando o crime deixa vestígio, a prova material está ali para ser examinada, e o CPP (art. 158) diz que o exame é indispensável e que a confissão do acusado não pode substituí-lo. Ex.: mesmo que o agressor diga 'fui eu, quebrei os dentes dele', o perito ainda precisa examinar a boca da vítima e descrever as lesões no laudo.", fonte: a(CPP, 'art. 158') },
  { t: "a confissão não o substitui", p: "Porque o processo penal busca a verdade dos fatos, e o vestígio é a prova que não depende da palavra de ninguém. Confissão pode ser mentirosa, retirada depois ou obtida sob pressão; o exame de corpo de delito descreve o que de fato aconteceu no corpo da vítima (CPP, art. 158). Ex.: um réu confessa ter dado um soco, mas o perito encontra fratura de mandíbula: é o laudo que mostra a gravidade real da lesão corporal.", fonte: a(CPP, 'art. 158') },
  { t: "o exame de corpo de delito é indispensável", p: "Porque, quando a infração deixa vestígio (uma lesão, um dente quebrado, uma marca), existe prova material que pode ser examinada, e a lei não aceita que ela seja trocada por testemunho ou confissão (CPP, art. 158). Só o exame descreve com precisão a lesão e permite classificá-la. Ex.: sem o exame da boca da vítima, o juiz não tem como saber se a perda dos dentes foi debilidade permanente da mastigação (lesão grave).", fonte: a(CPP, 'art. 158') },
  { t: "os peritos não oficiais PRESTAM compromisso", p: "Porque o perito oficial já tem um dever legal ligado ao cargo público; o nomeado para o caso não tem. O compromisso de 'bem e fielmente desempenhar o encargo' (CPP, art. 159, §2º) cria essa responsabilidade: se ele mentir no laudo, responde por falsa perícia. Ex.: dois dentistas nomeados pelo delegado assinam o termo de compromisso antes de examinar a vítima; a partir daí o laudo deles vale como o de um perito.", fonte: a(CPP, 'art. 159, §2º') },
  { t: "documenta a história do vestígio, do reconhecimento ao descarte", p: "Porque uma prova só vale se ninguém puder dizer que ela foi trocada, contaminada ou alterada no caminho. A cadeia de custódia (CPP, art. 158-A, incluído pela Lei 13.964/2019) registra quem coletou, como guardou, para onde mandou e quem examinou o vestígio. Ex.: o swab com saliva de uma marca de mordida vai lacrado, etiquetado e com registro de cada pessoa que o manuseou até o laboratório de DNA; se faltar um elo, a defesa pode pedir que a prova seja desconsiderada.", fonte: a(CPP, 'arts. 158-A a 158-F') },
  { t: "as vias de acesso do pescoço e da cabeça", p: "Porque é por essas vias que se chega à mandíbula, à maxila e às estruturas da boca que o perito-odontólogo precisa examinar, e é esse o limite da competência do cirurgião-dentista, que é a região da cabeça e do pescoço. A Lei 5.081, art. 6º, IX, autoriza isso na necropsia; o resto do corpo fica com o médico-legista. Ex.: para identificar um cadáver, o odontolegista pode fazer o acesso pela face e pelo pescoço para expor os dentes e radiografar a mandíbula.", fonte: a(L5081, 'art. 6º, IX') },

  /* ---------- Identificação humana ---------- */
  { t: "reconhecimento visual não é considerado preciso", p: "Porque, num desastre, o corpo costuma estar queimado, inchado, decomposto ou mutilado, e a família, em choque, tende a 'ver' quem espera ver. Já houve trocas de corpos entregues por reconhecimento. Por isso a INTERPOL exige métodos objetivos, os identificadores primários: impressões digitais, odontologia e DNA. Ex.: depois das chuvas de 2022 em Petrópolis, os corpos passaram por digitais e exame odontológico, e não só pela palavra dos parentes.", fonte: INT },
  { t: "vindos da casa da vítima ou da família", p: "Porque o dado ante mortem é o que foi registrado ENQUANTO a pessoa estava viva, e ele está espalhado: no prontuário do dentista, nos exames médicos, em objetos pessoais (escova de dentes, pente) com DNA, e nos parentes, que dão DNA para comparação. A equipe de DVI recolhe tudo isso para comparar com o post mortem. Ex.: a família entrega o nome do dentista da vítima e a escova de dentes dela; o perito pede ao dentista o prontuário e as radiografias.", fonte: INT },
  { t: "usado tanto no prontuário clínico", p: "Porque a identificação é uma comparação ponto a ponto, e ela só funciona se os dois registros falarem a mesma língua. O odontograma marca, dente por dente, ausências, restaurações, próteses e canais; o perito faz um odontograma post mortem no corpo e põe lado a lado com o ante mortem do dentista. Ex.: o prontuário mostra 36 ausente e coroa no 11; o corpo tem exatamente isso, e nenhuma discordância sem explicação.", fonte: INT },
  { t: "sem o registro ante mortem não há com o que comparar", p: "Porque identificar é COMPARAR: o exame do corpo (post mortem) sozinho descreve os dentes, mas não diz de quem eles são. Só o prontuário, o odontograma e as radiografias feitos em vida permitem dizer 'é essa pessoa'. É por isso que o Código de Ética obriga a manter o prontuário atualizado (CEO, art. 17). Ex.: um corpo com várias restaurações só é identificado quando aparece o prontuário do dentista dele com as mesmas restaurações.", fonte: a(INT + '; ' + CEO, 'art. 17') },
  { t: "uma coincidência comum sozinha não individualiza", p: "Porque muitos detalhes dos dentes são comuns na população: muita gente tem restauração de amálgama na oclusal do primeiro molar ou um dente extraído. Uma coincidência dessas pode acontecer por acaso entre duas pessoas diferentes. O que individualiza é um CONJUNTO de coincidências, de preferência com detalhes raros, sem nenhuma discordância inexplicável. Ex.: 'restauração no 36' não basta; 'restauração no 36, canal no 21 com pino, 18 incluso e prótese no 46', tudo batendo com a radiografia, identifica.", fonte: a(INT + '; ' + VAN, '') },
  { t: "ausência de discordância inexplicável", p: "Porque uma única diferença impossível exclui a identidade, por mais coincidências que existam. Um dente pode ser extraído ou restaurado depois do último registro (discordância explicável), mas um dente que estava ausente em vida não pode 'reaparecer' no corpo. O perito confere isso dente por dente no odontograma. Ex.: o prontuário diz que o 46 foi extraído em 2020 e o corpo tem o 46 hígido: não é a mesma pessoa, mesmo que as outras restaurações batam.", fonte: VAN },
  { t: "resistem a calor e decomposição", p: "Porque o esmalte é o tecido mais mineralizado do corpo (cerca de 96% de mineral), protegido ainda pelos lábios, bochechas e ossos da face. Ele aguenta temperaturas altas e não apodrece como os tecidos moles. A polpa, dentro do dente, fica protegida e pode guardar DNA. Ex.: num incêndio em que as digitais foram destruídas, os dentes e as restaurações continuam ali para comparar com a radiografia do dentista.", fonte: MAL },
  { t: "mas com a boca preservada", p: "Porque os dentes ficam dentro de uma cavidade protegida por lábios, bochechas, língua e ossos, e são o tecido mais duro do corpo. Mesmo quando as mãos queimam ou são destruídas (sem digitais), a boca muitas vezes continua examinável. Por isso a odontologia é um identificador primário da INTERPOL. Ex.: num acidente aéreo, o perito abre a boca da vítima, faz o odontograma e as radiografias e compara com o prontuário que a família trouxe.", fonte: a(INT + '; ' + MAL, '') },
  { t: "considera conclusivos as impressões digitais, a odontologia e o DNA", p: "Porque os três têm as mesmas qualidades: são individuais (variam de pessoa para pessoa), podem ser comparados com um registro feito em vida (RG, prontuário, DNA de parentes) e resistem relativamente bem. Reconhecimento visual, roupa e documentos no bolso podem enganar. Ex.: no voo 2283 (Vinhedo, 2024), o IML usou digitais e arcada dentária, que bastaram para identificar todas as 62 vítimas.", fonte: INT },
  { t: "sozinho, identifica a pessoa com segurança", p: "Porque o identificador primário compara uma característica individual com um registro confiável feito em vida, e aceita ser conferido por outro perito. Digital, comparação odontológica e DNA fazem isso; tatuagem, cicatriz e roupa são identificadores secundários, que só ajudam. Ex.: um corpo com tatuagem igual à da pessoa desaparecida ainda precisa da comparação odontológica ou da digital para a identificação ser fechada.", fonte: INT },
  { t: "estão entre os identificadores primários da INTERPOL", p: "Porque digitais e dentes permitem comparação direta com registros feitos em vida e chegam a resultado rápido. No Brasil, quase todo mundo tem digital no registro de identidade, e muita gente tem prontuário e radiografia no dentista. O DNA também é primário, mas é mais caro e demorado. Ex.: no voo 2283, digitais e arcada dentária resolveram todos os casos, e nenhum corpo precisou de DNA.", fonte: a(INT + '; ' + SBT, '') },
  { t: "nenhum corpo precisou de DNA", p: "Porque os métodos primários mais rápidos (digitais e exame odontológico) já bastaram: quando o corpo está preservado o suficiente e existem registros ante mortem, a comparação é direta. O DNA exige amostra de parente, laboratório e mais tempo, e fica reservado para os casos em que os outros falham. Ex.: no voo 2283 o IML liberou as 62 vítimas em menos de uma semana, sem esperar exame genético.", fonte: SBT },
  { t: "a comparação odontológica pode identificar sem esperar o DNA", p: "Porque, se o prontuário e as radiografias ante mortem existem, o odontolegista compara na hora com o odontograma e as radiografias post mortem. O DNA depende de achar parentes, colher amostra e processar no laboratório, o que pode levar semanas. Ex.: num acidente, o corpo sem digitais é identificado no mesmo dia porque o dentista da vítima, em Petrópolis, mandou a panorâmica de dois anos antes.", fonte: INT },
  { t: "etapa mais decisiva no protocolo", p: "Porque as impressões digitais são únicas e, no Brasil, ficam guardadas nos institutos de identificação desde a emissão da carteira de identidade: há registro ante mortem para quase todo adulto. A comparação é rápida e barata. Por isso a papiloscopia é a que mais identifica nas tragédias. Ex.: em Brumadinho, a papiloscopia identificou 183 das 267 vítimas do balanço de 2023.", fonte: a(MPRJ + '; ' + AGM, '') },
  { t: "o IML de Petrópolis adotaria métodos técnicos da INTERPOL", p: "Porque, com muitas vítimas ao mesmo tempo, o risco de troca de corpos aumenta, e o protocolo DVI da INTERPOL organiza o trabalho em fases (cena, post mortem, ante mortem, reconciliação) e exige identificadores primários. Seguir um padrão internacional dá segurança às famílias e ao processo. Ex.: nas chuvas de fevereiro de 2022, os corpos foram examinados pelo IML de Petrópolis com digitais, exame odontológico e genética forense.", fonte: a(MPRJ + '; ' + INT, '') },
  { t: "foi o método que mais identificou vítimas", p: "Porque a papiloscopia tem registro ante mortem para praticamente todo adulto (a digital tirada para a carteira de identidade), e a comparação é rápida. A odontologia depende de a vítima ter prontuário e radiografias, e o DNA, de amostra de parente e laboratório. Ex.: no balanço de Brumadinho de 24/01/2023, papiloscopia identificou 183 de 267 vítimas.", fonte: AGM },
  { t: "Mais de 10 % das identificações foram feitas pela Odontologia Legal", p: "Porque 32 de 267 dá cerca de 12%: em parte dos corpos, as mãos estavam muito danificadas para a papiloscopia, e os dentes, mais resistentes, continuavam comparáveis com o prontuário. Isso mostra o valor do odontograma e das radiografias bem guardados. Ex.: em Brumadinho, cada uma dessas 32 identificações dependeu de algum dentista ter registrado o tratamento da vítima em vida.", fonte: AGM },
  { t: "isso só funciona se o prontuário existir e estiver atualizado", p: "Porque o perito só identifica comparando o corpo com o que o dentista registrou em vida. Prontuário rasurado, sem data ou desatualizado não serve como dado ante mortem. Por isso o CEO, art. 9º, X e art. 17, obrigam a elaborar e manter atualizados os prontuários. Ex.: em Brumadinho, os peritos procuraram os dentistas das vítimas; quem tinha odontograma e radiografias recentes ajudou a fechar identificações.", fonte: a(CEO, 'arts. 9º, X e 17') },
  { t: "Os números mudam com o tempo", p: "Porque a identificação continua depois da tragédia: restos encontrados mais tarde, amostras de DNA que chegam depois e confirmações de laboratório vão alterando o balanço. Por isso todo número de identificação tem que vir com a fonte e a data. Ex.: o balanço de Brumadinho de 24/01/2023 (267 identificadas, 32 pela Odontologia Legal) é um retrato daquela data; outro balanço pode trazer números diferentes.", fonte: AGM },

  /* ---------- Estimativa de idade ---------- */
  { t: "por estágios de mineralização dentária na radiografia", p: "Porque os dentes se formam numa sequência e num ritmo bem previsíveis, começando antes de nascer e terminando por volta dos 20 anos, e essa formação aparece na radiografia mesmo antes de o dente nascer. O método de Demirjian classifica cada dente em estágios (A a H) e soma pontos que se convertem em idade dental. Ex.: na panorâmica de uma criança sem certidão, o perito vê o segundo pré-molar ainda sem raiz e calcula uma idade dental aproximada.", fonte: DEM },
  { t: "dentes permanentes inferiores do lado esquerdo", p: "Porque o método foi padronizado assim: os dentes inferiores aparecem com menos sobreposição na radiografia do que os superiores, e como os dois lados se formam quase iguais, basta um lado (o esquerdo, por convenção) para comparar com as tabelas. Usar sempre o mesmo lado deixa os resultados comparáveis entre peritos. Ex.: o perito estima a idade pelos sete dentes inferiores esquerdos da panorâmica, do incisivo central ao segundo molar.", fonte: DEM },
  { t: "o último a completar a formação", p: "Porque o terceiro molar começa a mineralizar por volta dos 8 a 10 anos e só fecha a raiz entre o fim da adolescência e o início da vida adulta, depois de todos os outros dentes. Por isso é o único que ainda está 'mudando' perto dos 18 anos, a idade da maioridade. Ex.: na panorâmica de um rapaz sem documento, o perito olha o estágio da raiz do siso para dizer se é provável que ele já tenha 18 anos.", fonte: PIN },
  { t: "estágio G aumenta muito a probabilidade de maioridade", p: "Porque no estágio G as paredes da raiz já estão quase paralelas e só falta fechar o ápice, ponto a que a maioria chega perto ou depois dos 18 anos. No estudo brasileiro de 2023 (1.087 panorâmicas), ter pelo menos um terceiro molar em G fez a probabilidade de ser adulto subir muito. Ainda assim é estimativa. Ex.: no laudo de idade de um jovem sem documento, o perito escreve 'alta probabilidade de ter 18 anos ou mais', e não 'tem 18 anos'.", fonte: PIN },
  { t: "a raiz só termina por volta dos 18 a 25 anos", p: "Porque o terceiro molar é o último dente da sequência de formação: ele começa tarde e a raiz demora anos para crescer e fechar o ápice. Essa variação grande (18 a 25 anos) vem da genética, do sexo e da população. Por isso o siso ajuda a estimar a maioridade, mas sempre com margem. Ex.: dois irmãos de 19 anos podem ter terceiros molares em estágios diferentes na panorâmica.", fonte: PIN },
  { t: "dentes permanentes feita com brasileiros", p: "Porque o ritmo de formação dos dentes muda de uma população para outra (genética, nutrição, clima), e uma tabela feita com crianças de outro país pode errar a idade de um brasileiro. A tabela de Nicodemo, Moraes e Médici Filho foi construída com brasileiros e é usada inclusive em software de estimativa de idade dental. Ex.: um perito do IML usa a tabela brasileira para estimar a idade de uma criança encontrada sem documento no Rio.", fonte: MOR },
  { t: "com margem de erro, e não substitui o documento", p: "Porque a idade dental mede a idade BIOLÓGICA dos dentes, e cada pessoa se desenvolve num ritmo um pouco diferente. O perito dá uma faixa provável, nunca a data de nascimento. Quando existe certidão ou RG válido, ele vale mais que qualquer estimativa. Ex.: uma criança de 8 anos com idade dental de 7 a 9 anos: o laudo informa a faixa e a probabilidade, e o juiz decide com as outras provas.", fonte: MOR },
  { t: "por isso se fala em probabilidade e intervalo", p: "Porque duas pessoas com a mesma idade podem ter os dentes em estágios diferentes (variação individual, sexo, população). Então o laudo não diz 'tem 17 anos', mas 'provavelmente entre X e Y anos' ou 'probabilidade Z de ter 18 anos ou mais'. Ex.: na estimativa de maioridade pelo terceiro molar, o perito informa a probabilidade, e o juiz decide se a pessoa responde como adulto ou pelo ECA.", fonte: PIN },
  { t: "o quanto o dente já se formou ajuda a estimar a idade", p: "Porque a formação da coroa e da raiz segue uma ordem e um tempo previsíveis, menos influenciados pelo ambiente do que a erupção (que pode atrasar por falta de espaço ou cárie no decíduo). Na radiografia, o perito vê em que ponto cada dente está e compara com tabelas como a de Demirjian ou a de Nicodemo. Ex.: um segundo molar com a raiz pela metade indica uma criança de uns 11 a 12 anos.", fonte: DEM },
  { t: "Para saber se alguém passou dos 18 anos, o decíduo não serve", p: "Porque os dentes decíduos já caíram por volta dos 12 anos: depois disso não há mais nada mudando neles para medir. Perto dos 18 anos, o único dente ainda em formação é o terceiro molar, por isso é ele que se usa na estimativa de maioridade. Ex.: na radiografia de um rapaz de 17 ou 19 anos, todos os decíduos já foram substituídos; o perito olha o estágio da raiz do siso.", fonte: PIN },
  { t: "a maioridade penal e civil começa aos 18 anos", p: "Porque a Constituição diz que os menores de 18 anos são penalmente inimputáveis (respondem pelo ECA, não pelo Código Penal) e o Código Civil fixa que a menoridade cessa aos 18 anos completos. Por isso a idade exata importa tanto quando falta documento, e a Justiça pede a perícia de estimativa de idade. Ex.: um jovem detido sem documento: se a perícia indicar provável maioridade, ele pode responder como adulto.", fonte: a(CF + '; ' + CC, 'CF art. 228; CC art. 5º') },

  /* ---------- Marcas de mordida ---------- */
  { t: "não tem base científica suficiente", p: "Porque a análise da marca de mordida depende de premissas que nunca foram comprovadas: que a arcada de cada pessoa é única, que essa unicidade fica registrada com fidelidade na pele e que o perito consegue comparar com precisão. A pele é elástica, se deforma, incha e cicatriza, e estudos mostraram peritos discordando entre si. Ex.: o mesmo formato de mordida pode ser 'compatível' com vários suspeitos; por isso não serve para apontar sozinho um autor.", fonte: NIST },
  { t: "suas premissas centrais não foram comprovadas", p: "Porque, para comparar a marca de mordida com a arcada, seria preciso provar três coisas: que cada dentição é única, que a pele registra esse desenho sem deformar e que dá para medir e comparar isso com confiabilidade. A revisão do NIST (2023) não encontrou dados que sustentem essas premissas. Ex.: a mesma mordida num braço que se mexia e numa coxa parada sai com formatos diferentes, mesmo sendo do mesmo agressor.", fonte: NIST },
  { t: "não deve ser usada para apontar sozinha um único autor", p: "Porque, se a técnica não tem base científica suficiente (NIST, 2023), usá-la como única prova de autoria pode condenar um inocente, como já aconteceu. A comparação do desenho pode no máximo excluir alguém (por exemplo, quem não tem dentes); a prova de autoria precisa vir de outro método, como o DNA da saliva. Ex.: na vítima mordida no braço, o perito coleta swab para DNA em vez de afirmar que a mordida 'é do suspeito'.", fonte: NIST },
  { t: "hoje é considerado pouco confiável", p: "Porque a pele não é um molde: ela estica, se curva, incha, forma hematoma e cicatriza, e a posição do corpo na hora da mordida muda o desenho. Dois peritos podem chegar a conclusões opostas sobre a mesma marca. A revisão do NIST de 2023 concluiu que falta base científica. Ex.: uma mordida no ombro fotografada no dia seguinte já está com o contorno mudado pelo inchaço.", fonte: NIST },
  { t: "a saliva pode ser fonte de DNA", p: "Porque a saliva carrega células que descamam da mucosa da boca e leucócitos, e essas células têm núcleo com DNA. Quando alguém morde, deixa saliva na pele, e esse DNA pode ser comparado com o de um suspeito. Ao contrário do desenho da mordida, o DNA é um identificador primário. Ex.: a vítima mordida chega ao IML e, antes de lavar a região, o perito passa um swab estéril no local.", fonte: MAL },
  { t: "o DNA da saliva vale mais", p: "Porque o DNA é um identificador primário com base científica sólida: é individual e a comparação é feita em laboratório com estatística conhecida. Já o desenho da mordida é distorcido pela pele e não tem base científica suficiente (NIST, 2023). Ex.: num caso de agressão em Petrópolis, o swab da marca de mordida mandado para o laboratório pode apontar o agressor, enquanto a foto da marca só descreve a lesão.", fonte: a(MAL + '; ' + NIST, '') },
  { t: "que foi justamente o que inocentou condenados por mordida", p: "Porque, quando os testes de DNA ficaram disponíveis, a saliva e o sangue guardados como prova puderam ser analisados, e em alguns casos o DNA não era do condenado. A mesma marca de mordida que tinha sido usada contra ele, pela comparação do desenho, acabou servindo para inocentá-lo. Ex.: no caso de Phoenix (Arizona), o DNA da saliva e do sangue na vítima excluiu o condenado em 2002 e apontou outro homem.", fonte: a(INO + '; ' + MAL, '') },
  { t: "um passo que pode ser o mais valioso", p: "Porque o DNA da saliva é frágil: lavar, enxugar, aplicar pomada ou até moldar a região pode remover ou contaminar as células. Por isso o swab estéril vem ANTES da foto e da moldagem, e entra na cadeia de custódia. E o DNA, ao contrário do desenho, pode identificar o autor. Ex.: a enfermeira que vai limpar a ferida espera o perito passar o swab na marca de mordida.", fonte: MAL },
  { t: "A comparação do DESENHO é que perdeu confiabilidade", p: "Porque o desenho depende de a pele registrar fielmente os dentes, o que não acontece: a pele estica, se move e cicatriza. O material biológico (saliva) não sofre esse problema, e o DNA dele pode ser comparado com segurança. Por isso a marca de mordida continua sendo coletada, mas pelo DNA. Ex.: o perito fotografa a marca para descrever a lesão, mas a autoria se discute pelo resultado do laboratório.", fonte: a(NIST + '; ' + MAL, '') },
  { t: "Haste com algodão (ou outra fibra) estéril", p: "Porque o swab vai buscar uma quantidade muito pequena de DNA, e qualquer DNA de outra pessoa (de quem fabricou, embalou ou manuseou a haste) contaminaria a amostra e poderia dar um resultado falso. Por isso ele é estéril, usado com luva e guardado lacrado, entrando na cadeia de custódia. Ex.: o perito abre o swab na frente da vítima, passa na marca de mordida e lacra no envelope com etiqueta.", fonte: MAL },
  { t: "polpa do dente e ossos", p: "Porque a polpa fica fechada dentro do dente, protegida pelo esmalte e pela dentina, e o osso compacto também protege suas células do calor e da decomposição. Mesmo quando a pele e os músculos já se perderam, ainda dá para extrair DNA dali. Ex.: numa ossada antiga, o laboratório extrai DNA de um molar ou do fêmur e compara com o de um filho da pessoa desaparecida.", fonte: MAL },
  { t: "A parte compacta protege bem o DNA", p: "Porque o osso compacto é denso e mineralizado, então deixa entrar pouca água, pouca bactéria e pouco oxigênio, que são o que destrói o DNA. As células presas dentro dele ficam preservadas por muito tempo. Ex.: no caso da ossada de Embu, o DNA comparado em 1992 com o do filho e o da esposa foi extraído do fêmur, mesmo anos depois da morte.", fonte: JEF },

  /* ---------- Prontuário e documentos ---------- */
  { t: "com data, hora, nome, assinatura e número de registro", p: "Porque o prontuário é prova: ele precisa mostrar O QUE foi feito, QUANDO e POR QUEM. A ordem cronológica e a data e hora mostram a sequência do tratamento; nome, assinatura e número no CRO mostram a autoria. Anotação a lápis, sem data ou sem assinatura pode ser contestada no processo. O CEO exige isso no art. 17, parágrafo único. Ex.: num processo por extração do dente errado, o prontuário assinado e datado mostra o que o dentista planejou e o que o paciente autorizou.", fonte: a(CEO, 'art. 17') },
  { t: "20 anos a partir do último registro", p: "Porque o prontuário serve de prova por muito tempo: um dano pode ser descoberto anos depois (o prazo de 5 anos do CDC só começa quando o paciente conhece o dano e o autor), e o prontuário também é dado ante mortem para identificar alguém. A Lei 13.787/2018 (art. 6º) fixou o mínimo de 20 anos contados do ÚLTIMO registro, não do primeiro atendimento. Ex.: paciente atendido de 2010 a 2025: o prontuário dele fica guardado pelo menos até 2045.", fonte: a(L13787, 'art. 6º') },
  { t: "deixar de fornecer cópia quando solicitada", p: "Porque as informações do prontuário são do paciente: ele precisa delas para continuar o tratamento com outro profissional, para pedir segunda opinião ou para se defender. O dentista é o guardião do documento, não o dono das informações. O CEO, art. 18, I, faz da recusa uma infração ética, e a LGPD, art. 18, também garante acesso aos dados. Ex.: a paciente que vai trocar de dentista em Petrópolis pede a cópia, com radiografias, e o dentista entrega e fica com o original.", fonte: a(CEO, 'art. 18, I') },
  { t: "salvo quando isso cause risco ao próprio paciente ou a terceiros", p: "Porque o direito de acesso não pode virar um dano: em situações raras, uma informação dada de forma brusca pode prejudicar o próprio paciente ou expor outra pessoa. O CEO, art. 18, I, abre essa exceção, mas ela é estreita e tem de ser justificada no prontuário. Ex.: um prontuário com informação sigilosa sobre um familiar que também é paciente; o dentista fornece a cópia sem expor o dado do outro.", fonte: a(CEO, 'art. 18, I') },
  { t: "deve garantir integridade, autenticidade e confidencialidade", p: "Porque o prontuário digitalizado só pode substituir o papel se provar que não foi alterado (integridade), que veio de quem diz que veio (autenticidade) e que só quem pode lê (confidencialidade). Por isso a Lei 13.787/2018 (art. 2º) exige certificado digital ICP-Brasil ou outro padrão legalmente aceito. Ex.: a clínica escaneia as fichas antigas e assina cada arquivo com o e-CNPJ, e o sistema registra qualquer mudança.", fonte: a(L13787, 'art. 2º') },
  { t: "análise obrigatória de comissão permanente de revisão", p: "Porque destruir o original é irreversível. A comissão confere se a digitalização ficou completa, legível e assinada, e se aquele prontuário não tem valor histórico ou de prova que exija guardar o papel. A Lei 13.787/2018 (art. 3º) exige essa análise antes de destruir. Ex.: a clínica escaneou 5 mil fichas; antes de mandar o papel para a fragmentadora, a comissão confere por amostragem e registra a decisão.", fonte: a(L13787, 'art. 3º') },
  { t: "tem o mesmo valor probatório do original", p: "Porque, cumpridas as exigências de integridade e autenticidade (certificado ICP-Brasil), o arquivo digital é tão confiável quanto o papel, e a Lei 13.787/2018 (art. 5º) lhe dá o mesmo valor de prova para todos os fins de direito. Ex.: num processo de responsabilidade civil, o dentista apresenta o prontuário digitalizado e assinado, e o juiz o aceita como se fosse a ficha de papel.", fonte: a(L13787, 'art. 5º') },
  { t: "com certificado ICP-Brasil tem o mesmo valor do original", p: "Porque a assinatura com certificado ICP-Brasil usa criptografia que liga o documento a uma pessoa e denuncia qualquer alteração depois de assinado. Por isso a lei presume que é autêntico e íntegro, e a Lei 13.787/2018 (art. 5º) dá ao prontuário digitalizado assim o mesmo valor de prova do papel. Ex.: o dentista assina o prontuário eletrônico com o e-CPF; se alguém mudar uma vírgula, a assinatura deixa de valer.", fonte: a(L13787, 'arts. 2º e 5º') },
  { t: "garante autoria e que não foi alterado", p: "Porque o certificado ICP-Brasil usa um par de chaves: só o dono tem a chave privada que assina, e qualquer pessoa confere a assinatura com a chave pública. Se o documento mudar depois, a conferência falha. Por isso a assinatura com ele tem presunção de veracidade (MP 2.200-2/2001, art. 10, §1º). Ex.: o laudo assinado digitalmente pelo perito não pode ser alterado por ninguém sem que isso apareça.", fonte: 'Medida Provisória 2.200-2/2001 (ICP-Brasil), https://www.planalto.gov.br/ccivil_03/mpv/antigas_2001/2200-2.htm, art. 10, §1º; ' + L13787 },
  { t: "sem ter praticado ato profissional que o justifique", p: "Porque o atestado é uma afirmação do dentista que terceiros (empregador, escola, Justiça) aceitam como verdade por confiança na profissão. Atestar sem ter atendido é declarar algo que não aconteceu, o que é infração ética (CEO, art. 18, III) e pode ser crime de falsidade. Ex.: um amigo pede 3 dias de afastamento sem ter consultado: o dentista não pode atestar; se tivesse feito uma exodontia de siso nele, poderia.", fonte: a(CEO, 'art. 18, III') },
  { t: "O atestado tem de corresponder a ato realmente praticado", p: "Porque a Lei 5.081 (art. 6º, III) dá ao dentista o poder de atestar, inclusive para justificar falta ao emprego, mas esse poder só vale para o que ele de fato fez. O empregador aceita o atestado por confiar na profissão; um atestado falso quebra essa confiança e é infração ética (CEO, art. 18, III). Ex.: depois da exodontia de dois terceiros molares, o dentista atesta 2 dias de repouso, com data e CRO.", fonte: a(CEO, 'art. 18, III') },
  { t: "proíbe assinar em branco receituários", p: "Porque a assinatura é o que dá valor ao documento: uma folha assinada em branco pode ser preenchida por qualquer pessoa com qualquer coisa, inclusive receita de medicamento controlado ou atestado falso, e a responsabilidade será de quem assinou. O CEO, art. 18, VII, faz disso uma infração ética. Ex.: a secretária preenche uma receita de antibiótico numa folha assinada em branco para um parente; o dentista responde pelo que ela escreveu.", fonte: a(CEO, 'art. 18, VII') },
  { t: "diz, por escrito, que entendeu e autoriza", p: "Porque o consentimento só vale se o paciente foi informado, e a forma escrita é a prova de que isso aconteceu: mostra o que foi explicado (riscos, alternativas, custos) e que ele concordou. Numa ação de responsabilidade civil, sem o TCLE fica a palavra de um contra a do outro. Ex.: antes da exodontia de um siso incluso, o paciente assina o TCLE que cita o risco de parestesia do lábio.", fonte: a(CEO, 'art. 11, IV e X') },
  { t: "as radiografias guardadas no prontuário são dados ante mortem valiosos", p: "Porque a radiografia registra detalhes que o olho não vê e que são muito individuais: forma das raízes, tratamento de canal, pinos, padrão do osso, seios da face. Na identificação, o perito faz uma radiografia post mortem na mesma posição e compara. Ex.: uma panorâmica de 2023 guardada pelo dentista de Petrópolis permite identificar um corpo comparando o canal do 21 e o implante do 46.", fonte: VAN },

  /* ---------- Responsabilidade civil ---------- */
  { t: "Mediante a verificação de culpa", p: "Porque o profissional liberal (como o dentista autônomo) trabalha com o corpo do paciente, que reage de forma imprevisível, e em geral assume uma obrigação de meio: usar a técnica correta, não garantir o resultado. Por isso o CDC, art. 14, §4º, abre exceção à regra do fornecedor: o paciente precisa mostrar negligência, imprudência ou imperícia. Ex.: um implante que não se fixou no osso num fumante não gera indenização se o dentista seguiu a técnica e registrou tudo no prontuário.", fonte: a(CDC, 'art. 14, §4º') },
  { t: "fornecedor de serviços responde independentemente de culpa", p: "Porque o CDC parte da ideia de que quem oferece um serviço no mercado assume os riscos dele e lucra com ele, enquanto o consumidor é a parte mais fraca e não consegue provar o que acontece por dentro da empresa. Por isso o art. 14 do CDC adota a responsabilidade objetiva: basta o dano e o nexo com o serviço. Ex.: a clínica (pessoa jurídica) em que o paciente foi atendido responde pelo dano mesmo sem se provar culpa de alguém.", fonte: a(CDC, 'art. 14') },
  { t: "responde pelos danos independentemente de culpa", p: "Porque a pessoa jurídica é fornecedora de serviços e, pelo art. 14 do CDC, responde objetivamente: o paciente só precisa mostrar o dano e o nexo com o serviço. A culpa pessoal só é discutida no caso do profissional liberal (§4º). A clínica pode depois cobrar do dentista que errou. Ex.: uma franquia de clínicas em Petrópolis é condenada a indenizar o paciente por uma prótese mal adaptada, sem discutir qual dentista falhou.", fonte: a(CDC, 'art. 14') },
  { t: "o paciente precisa mostrar negligência, imprudência ou imperícia", p: "Porque, sendo a responsabilidade pessoal do profissional liberal apurada mediante verificação de culpa (CDC, art. 14, §4º), quem acusa tem de mostrar a falha: descuido (negligência), ação sem cautela (imprudência) ou falta de conhecimento técnico (imperícia). Muitas vezes isso se faz pela perícia. Ex.: o paciente que teve o nervo lesado numa extração precisa de laudo mostrando que a técnica foi errada, e não só que a parestesia apareceu.", fonte: a(CDC, 'art. 14, §4º') },
  { t: "a partir do conhecimento do dano e de sua autoria", p: "Porque ninguém pode processar por um dano que ainda não conhece, nem processar alguém que não sabe quem é. Por isso o CDC, art. 27, conta os 5 anos a partir do momento em que o paciente descobre o dano E quem o causou, e não da data do tratamento. Ex.: uma paciente descobre hoje, numa radiografia, um instrumento fraturado no canal feito há 8 anos: o prazo de 5 anos começa agora.", fonte: a(CDC, 'art. 27') },
  { t: "ainda que exclusivamente moral", p: "Porque a Constituição (art. 5º, V e X) protege a honra, a imagem e a intimidade e garante indenização por dano moral, mesmo sem prejuízo em dinheiro. O Código Civil, art. 186, define como ato ilícito violar direito e causar dano 'ainda que exclusivamente moral', e o art. 927 obriga a reparar. Ex.: o paciente que ficou com o sorriso deformado e passou vergonha no trabalho pode receber danos morais, mesmo sem ter gasto nada.", fonte: a(CC + '; ' + CF, 'CC arts. 186 e 927; CF art. 5º, V e X') },
  { t: "mesmo sem nenhum prejuízo em dinheiro", p: "Porque o dano moral atinge a pessoa e não o bolso: dor, humilhação, vergonha, ofensa à imagem. A Constituição (art. 5º, X) garante indenização por esse tipo de dano, e o Código Civil (art. 186) considera ato ilícito o dano 'ainda que exclusivamente moral'. Ex.: dentista que expõe a radiografia e o nome de um paciente nas redes sociais pode ser condenado por dano moral, mesmo que o paciente não tenha perdido dinheiro.", fonte: a(CC + '; ' + CF, 'CC art. 186; CF art. 5º, X') },
  { t: "A Justiça pode mandar indenizar separado do dano moral", p: "Porque são danos diferentes: o dano estético é a alteração visível e duradoura no corpo (cicatriz, assimetria), e o dano moral é o sofrimento e a ofensa à dignidade. O STJ firmou na Súmula 387 que é lícito somar as duas indenizações. Ex.: no REsp 2.225.449 (2026), os dentistas foram condenados a pagar danos morais E estéticos pela assimetria facial depois da cirurgia ortognática.", fonte: 'STJ, Súmula 387, https://www.stj.jus.br/; ' + STJ },
  { t: "Sem nexo, não há responsabilidade", p: "Porque só se responde pelo dano que o próprio ato causou. Se a lesão veio de outra coisa (doença do paciente, falta de cuidado dele, outro profissional), não há ligação entre o ato e o dano, e não há dever de indenizar. Por isso o perito sempre investiga o nexo causal. Ex.: a prótese quebrou porque o paciente mordeu um caroço e contou isso no retorno, registrado no prontuário: o dentista não responde pela fratura.", fonte: a(CC, 'arts. 186, 403 e 927') },
  { t: "A Justiça costuma aplicar à odontologia estética", p: "Porque no tratamento estético o paciente não está doente e procura um resultado específico (um sorriso, uma forma); quando o profissional promete esse resultado, assume obrigação de resultado. Se o resultado não vem, presume-se a culpa, e cabe ao dentista provar uma causa que o afaste. Ex.: no REsp 2.225.449 (2026), uma cirurgia estético-funcional com promessa de melhora estética foi tratada como obrigação de resultado.", fonte: STJ },
  { t: "Obrigação de resultado, com culpa presumida", p: "Porque, quando o profissional faz uma promessa de resultado (ex.: melhora estética prometida nos documentos do tratamento) e ele não acontece, a lei inverte a lógica: não é o paciente quem prova a culpa, é o profissional quem precisa provar que o resultado falhou por outra causa (culpa do paciente, caso fortuito). Ex.: no REsp 2.225.449, a promessa de melhora estética registrada pesou para o tribunal presumir a culpa dos dois dentistas.", fonte: STJ },
  { t: "porque exigiria rever provas", p: "Porque o STJ existe para uniformizar a interpretação da lei federal no país (CF, art. 105, III), e não para julgar os fatos de novo. A Súmula 7 diz que a pretensão de simples reexame de prova não enseja recurso especial. Quem avalia o laudo pericial é o juiz e o tribunal do estado. Ex.: no REsp 2.225.449, o STJ não discutiu se a cirurgia era estética, porque isso dependia do laudo; só decidiu a questão jurídica da nova cirurgia.", fonte: a('STJ, Súmula 7; ' + CF + '; ' + STJ, 'CF art. 105, III') },
  { t: "cobrar as duas coisas seria enriquecimento sem causa", p: "Porque, quando o contrato falha, o paciente escolhe: ou exige o cumprimento (que se faça o serviço direito), ou desfaz o contrato e recebe o dinheiro de volta (CC, art. 475). Receber o dinheiro de volta E ainda fazer o dentista pagar outra cirurgia seria ganhar duas vezes pelo mesmo prejuízo, o enriquecimento sem causa que o CC, art. 884, proíbe. Ex.: no REsp 2.225.449, o paciente que já tinha recebido o valor pago não pôde exigir também o custeio de nova operação.", fonte: a(STJ + '; ' + CC, 'arts. 475 e 884') },
  { t: "Quem enriqueceu sem causa tem de devolver", p: "Porque o direito não aceita que alguém ganhe às custas de outro sem um motivo jurídico (contrato, lei, decisão). O Código Civil, art. 884, chama isso de enriquecimento sem causa e manda restituir o que foi recebido indevidamente. Ex.: o paciente que recebeu duas vezes o reembolso do mesmo tratamento, por erro da clínica, tem de devolver o valor a mais.", fonte: a(CC, 'art. 884') },
  { t: "responsabilidade solidária dos dois cirurgiões-dentistas", p: "Porque, quando o dano tem mais de um autor, todos respondem juntos pela reparação: o Código Civil, art. 942, diz que, se a ofensa tiver mais de um autor, todos responderão solidariamente. Assim o paciente pode cobrar o valor inteiro de qualquer um deles, e quem pagar acerta depois com o outro. Ex.: no REsp 2.225.449, os dois cirurgiões que operaram juntos ficaram responsáveis pela indenização inteira.", fonte: a(CC + '; ' + STJ, 'art. 942') },
  { t: "Não é regra para toda a Odontologia", p: "Porque o STJ só manteve a conclusão do tribunal do Rio sobre AQUELE caso (cirurgia estético-funcional com promessa de melhora estética) e não reexaminou provas. A regra geral do profissional liberal continua sendo a da verificação de culpa (CDC, art. 14, §4º), e a maior parte dos tratamentos é obrigação de meio, porque a resposta biológica do paciente varia. Ex.: um tratamento de canal num dente com lesão grande não garante a cura; o dentista se compromete com a técnica.", fonte: a(STJ + '; ' + CDC, 'art. 14, §4º') },
  { t: "pode ser usado como prova num processo", p: "Porque tudo o que o dentista escreve (prontuário, orçamento, TCLE, mensagem, post) registra o que foi combinado, e o juiz pode usar esses documentos para saber o que foi prometido. Uma promessa de resultado escrita pode transformar a obrigação em obrigação de resultado. Ex.: no REsp 2.225.449, os documentos do tratamento com a promessa de melhora estética pesaram para o tribunal presumir a culpa.", fonte: STJ },
  { t: "registrar bem e não prometer resultado", p: "Porque o prontuário completo e o TCLE são a melhor defesa do dentista (mostram o que foi explicado e feito), enquanto a promessa de resultado vira prova contra ele e é proibida na publicidade (Res. CFO-196/2019, art. 2º, §1º). Ex.: em vez de escrever 'sorriso perfeito garantido', o dentista registra no TCLE os objetivos, os riscos e que a resposta biológica pode variar.", fonte: a(R196 + '; ' + STJ, 'art. 2º, §1º') },
  { t: "pode transformar a obrigação em obrigação de resultado", p: "Porque quem promete um resultado assume o compromisso de entregá-lo, e não só de usar a técnica correta. Se o resultado prometido não vem, a culpa passa a ser presumida, e o dentista é quem precisa provar que a falha teve outra causa. Ex.: no REsp 2.225.449, a promessa de melhora estética escrita nos documentos levou o tribunal a tratar a cirurgia como obrigação de resultado.", fonte: STJ },

  /* ---------- Código de Ética, processo e penas ---------- */
  { t: "continua sendo o Código da 118/2012", p: "Porque as resoluções que vieram depois (como a CFO-271/2025) só mudaram incisos específicos, sem revogar o Código inteiro. O texto base, a estrutura e a numeração dos artigos continuam os da Res. CFO-118/2012. Ex.: depois de 2025, quem estuda o sigilo continua citando o art. 14 do Código de Ética da 118/2012, só que na versão atualizada.", fonte: R271 },
  { t: "Prisão é pena criminal, não ética", p: "Porque o Conselho Regional é um órgão de fiscalização da profissão e só aplica as penas que a lei lhe deu: advertência, censura, suspensão e cassação (Lei 4.324/1964, art. 18; CEO, art. 51). Tirar a liberdade de alguém só pode ser decidido pelo Poder Judiciário, num processo criminal. Ex.: o dentista que emitiu atestado falso pode ter censura pública no CRO e, num processo criminal separado, responder por falsidade.", fonte: a(CEO + '; ' + L4324, 'art. 51') },
  { t: "em dobro na reincidência", p: "Porque quem repete a infração mostra que a primeira pena não bastou, e a multa em dobro serve para desestimular a repetição. O CEO, art. 57, permite multa de 1 a 25 anuidades, dobrada quando o profissional reincide. Ex.: um dentista multado por publicidade com preço que, um ano depois, volta a anunciar 'clareamento a R$ 99,00' pode levar multa dobrada.", fonte: a(CEO, 'art. 57') },
  { t: "A pena ética mais leve", p: "Porque a advertência confidencial é só um aviso reservado: ninguém de fora fica sabendo e o profissional não perde o direito de trabalhar. A ordem do CEO, art. 51, vai da mais leve à mais grave (advertência confidencial, censura confidencial, censura pública, suspensão até 30 dias e cassação), para a pena ser proporcional à infração. Ex.: um dentista que esqueceu o número do CRO num anúncio, sem outra falha, tende a receber advertência confidencial.", fonte: a(CEO, 'art. 51') },
  { t: "precisa ser confirmada pelo Conselho Federal", p: "Porque a cassação tira do profissional o direito de exercer a profissão, a pena mais grave que existe na via ética. Por isso a decisão do Conselho Regional é 'ad referendum' do Conselho Federal, uma segunda instância obrigatória que confere o processo antes de a pena valer (CEO, art. 51). Ex.: o CRO-RJ decide cassar um dentista; a cassação só produz efeito depois de o CFO confirmar.", fonte: a(CEO + '; ' + L4324, 'art. 51') },
  { t: "Quem descumpre pode ser processado no CRO", p: "Porque os Conselhos Regionais foram criados pela Lei 4.324/1964 justamente para fiscalizar a profissão e julgar as infrações éticas, e o Código de Ética é a regra que eles aplicam. O processo ético é separado do processo na Justiça. Ex.: um paciente de Petrópolis que se sentiu enganado por um anúncio pode denunciar o dentista ao CRO-RJ, que abre processo ético.", fonte: a(L4324 + '; ' + CEO, '') },
  { t: "o mesmo fato pode gerar os três", p: "Porque cada esfera protege uma coisa diferente: a ética protege a profissão (CRO), a civil repara o dano do paciente (indenização) e a criminal pune a conduta que a lei define como crime. Uma não depende da outra. Ex.: o dentista que lesou o nervo por imperícia e escondeu o erro pode responder no CRO (processo ético), pagar indenização (responsabilidade civil) e responder por lesão corporal culposa.", fonte: a(CEO + '; ' + CC + '; ' + CP, '') },
  { t: "o próprio inciso limita o dever à falta de outro profissional", p: "Porque o dever de atender urgência existe para que o paciente não fique sem socorro. Se há outro cirurgião-dentista em condições de atender, o paciente tem a quem recorrer e a recusa não o deixa desamparado. Por isso o CEO, art. 11, VII, só torna infração ética a recusa quando não há outro profissional disponível. Ex.: numa cidade pequena com um só dentista, recusar uma dor forte de pulpite é infração; num centro com plantão odontológico ao lado, não.", fonte: a(CEO, 'art. 11, VII') },
  { t: "Comunicar previamente, por escrito, ao paciente ou responsável", p: "Porque a renúncia não pode deixar o paciente no meio do tratamento sem saber o que fazer. A comunicação escrita prova que ele foi avisado a tempo de procurar outro profissional, e as informações passadas ao sucessor garantem a continuidade (CEO, art. 5º, V). Ex.: o dentista que decide parar um tratamento de canal manda carta ao paciente e entrega ao novo dentista as radiografias e o que já foi feito.", fonte: a(CEO, 'art. 5º, V') },
  { t: "Sem isso pode configurar abandono", p: "Porque largar o paciente no meio do tratamento, sem aviso e sem passar as informações, pode deixar um dente aberto, uma infecção ou uma prótese provisória sem acompanhamento. O CEO, art. 11, VI, faz do abandono uma infração ética, salvo motivo justificável com aviso ao paciente. Ex.: o dentista que some depois de abrir um canal, sem avisar, comete abandono; o que avisa por escrito e entrega o prontuário ao colega faz uma renúncia legítima.", fonte: a(CEO, 'arts. 5º, V e 11, VI') },
  { t: "ainda que solicitados ou consentidos pelo paciente", p: "Porque quem tem o conhecimento técnico é o dentista: o paciente pode pedir algo inadequado por não saber os riscos. O consentimento autoriza um tratamento correto, mas não transfere a responsabilidade técnica. Por isso o CEO, art. 9º, XIV, manda o profissional assumir a responsabilidade pelo que fez, mesmo a pedido. Ex.: o paciente insiste em extrair dentes saudáveis para colocar prótese total; se o dentista faz, responde pelo tratamento desnecessário.", fonte: a(CEO, 'art. 9º, XIV') },
  { t: "veda executar tratamento desnecessário", p: "Porque todo procedimento tem risco, custo e às vezes é irreversível (desgaste de dente sadio, extração). Fazer algo de que o paciente não precisa é expô-lo a dano sem benefício e pode ser forma de lucrar com a confiança dele. O CEO, art. 11, V, faz disso uma infração ética. Ex.: indicar facetas em 10 dentes sadios só porque o paciente quer o dente 'mais branco', quando um clareamento resolveria.", fonte: a(CEO, 'art. 11, V') },
  { t: "as restrições à aceitação de cartões de desconto", p: "Porque o CADE entendeu (agosto de 2023) que proibir dentistas de aceitar cartões de desconto e de dar descontos limitava a livre concorrência, protegida pela Lei 12.529/2011, e determinou que o CFO tirasse essas restrições. A Res. CFO-271/2025 cumpriu a decisão. Ex.: hoje uma clínica pode aceitar um cartão de desconto sem cometer infração ética, mas continua proibida de anunciar preço como chamariz.", fonte: a(R271, 'arts. 1º a 3º') },
  { t: "brinde, premiação e sorteio", p: "Porque oferecer tratamento como prêmio transforma a saúde em mercadoria e atrai o paciente pela vantagem, não pela necessidade. O CEO manda o dentista se abster de atos que impliquem mercantilização da Odontologia (art. 9º, XIII), e a Res. CFO-271/2025 manteve essa proibição. Ex.: sortear um clareamento entre os seguidores do Instagram da clínica continua sendo infração ética.", fonte: a(R271 + '; ' + CEO, 'art. 9º, XIII') },
  { t: "telemarketing ativo, caixas de som em veículos e plaqueteiros", p: "Porque essas formas de propaganda vão atrás do paciente de forma insistente, para aliciar quem nem procurou tratamento, o que é mercantilização da Odontologia. A Res. CFO-271/2025 mudou as regras de desconto, mas manteve essa proibição na nova redação do art. 44, XIV. Ex.: uma clínica que paga pessoas para entregar panfletos com placas no centro de Petrópolis comete infração ética.", fonte: a(R271 + '; ' + CEO, 'art. 9º, XIII') },

  /* ---------- Sigilo e consentimento ---------- */
  { t: "Conversa com amigos não é justa causa", p: "Porque justa causa é um motivo que a própria norma aceita para revelar o segredo (notificação compulsória, colaboração com a Justiça, perícia, defesa de interesse legítimo, responsável pelo incapaz: CEO, art. 14, parágrafo único). Comentar com amigos não protege ninguém, só expõe o paciente, mesmo sem citar o nome, porque detalhes podem identificá-lo. Ex.: contar num churrasco em Petrópolis 'atendi a professora da escola X com prótese' já identifica a paciente.", fonte: a(CEO, 'art. 14') },
  { t: "proíbe referir casos clínicos identificáveis", p: "Porque o paciente confiou ao dentista dados de saúde (dados pessoais sensíveis) e a própria imagem, e expor isso fere o sigilo e a privacidade. O CEO, art. 14, III, proíbe exibir caso identificável em qualquer meio, salvo na docência ou em publicação científica com autorização. Ex.: postar a radiografia com o nome do paciente ou o rosto dele num story é infração, mesmo que o caso tenha ficado bonito.", fonte: a(CEO, 'art. 14, III') },
  { t: "não é quebra de sigilo profissional", p: "Porque cobrar honorários na Justiça é estrita defesa de interesse legítimo do profissional, uma das justas causas do CEO (art. 14, parágrafo único, IV), e o art. 15 trata dessa cobrança. Sem descrever o que foi feito, o dentista não conseguiria provar que o serviço existiu. Mas ele revela só o necessário para a cobrança. Ex.: na ação de cobrança, o dentista junta o orçamento aprovado e o prontuário do tratamento, sem expor outras informações de saúde.", fonte: a(CEO, 'arts. 14 e 15') },
  { t: "o sigilo não termina com o tratamento", p: "Porque a informação de saúde continua sendo do paciente e continua podendo prejudicá-lo depois (no trabalho, na família, no seguro). O dever de sigilo é permanente (CEO, art. 9º, VIII; art. 14), e as exceções são só as justas causas. Ex.: anos depois do fim do tratamento, o dentista não pode contar ao empregador do ex-paciente que ele tinha uma doença infecciosa.", fonte: a(CEO, 'arts. 9º, VIII e 14') },
  { t: "o sigilo continua valendo depois que o tratamento acaba", p: "Porque o que o dentista soube pela profissão continua sendo um segredo do paciente; terminar o tratamento não muda isso. A exceção da cobrança de honorários (CEO, arts. 14 e 15) permite revelar só o necessário para cobrar, não liberar tudo. Ex.: na cobrança judicial, o dentista descreve as próteses feitas, mas não conta que o paciente é soropositivo.", fonte: a(CEO, 'arts. 9º, VIII, 14 e 15') },
  { t: "como violência contra criança, idoso e mulher", p: "Porque essas vítimas muitas vezes não conseguem pedir ajuda sozinhas, e o profissional de saúde pode ser o único a ver os sinais (dente quebrado, lesão no lábio, hematoma na face). Por isso a lei manda comunicar às autoridades, e essa notificação compulsória é justa causa para quebrar o sigilo (CEO, art. 14, parágrafo único, I). O ECA, art. 13, manda comunicar ao Conselho Tutelar a suspeita de maus-tratos contra criança. Ex.: dentista que atende criança com fratura dental e lesões repetidas na boca notifica o caso.", fonte: a(ECA + '; ' + CEO, 'art. 13') },
  { t: "Deixar de esclarecer propósitos, riscos, custos e alternativas", p: "Porque o paciente só pode decidir sobre o próprio corpo se entender o que vai ser feito, o que pode dar errado, quanto custa e quais as outras opções. Sem informação não há consentimento de verdade, e o CEO, art. 11, IV, torna essa omissão uma infração ética. Ex.: antes da exodontia do siso, o dentista explica o risco de parestesia, o custo e a opção de acompanhar o dente, e registra no TCLE.", fonte: a(CEO, 'art. 11, IV') },
  { t: "sem consentimento prévio fora de urgência ou emergência", p: "Porque, em urgência ou emergência, esperar a autorização pode custar a vida ou a saúde do paciente, e se presume que ele aceitaria ser socorrido. Fora disso, ninguém pode mexer no corpo de outra pessoa sem a concordância dela (CEO, art. 11, X). Ex.: o paciente que desmaia com reação alérgica recebe a medicação de urgência na hora; já uma extração eletiva só começa depois de ele concordar.", fonte: a(CEO, 'art. 11, X') },
  { t: "exige anamnese, explicação dos riscos e consentimento do paciente", p: "Porque a exodontia é um procedimento cirúrgico, com risco de sangramento, infecção, fratura e lesão de nervo, e o resultado depende da saúde geral do paciente. A anamnese mostra os riscos (anticoagulante, diabetes), e o consentimento informado é exigido pelo CEO, art. 11, IV e X. Ex.: antes de extrair um terceiro molar incluso, o dentista pergunta sobre medicamentos e explica o risco de parestesia no TCLE.", fonte: a(CEO, 'art. 11, IV e X') },
  { t: "no exercício da docência ou em publicação científica", p: "Porque ensinar e publicar ciência precisa de casos reais, e isso traz benefício para a profissão e para outros pacientes. Mesmo assim, o CEO, art. 14, III, exige a autorização do paciente ou responsável e finalidade didático-acadêmica, porque a imagem e o prontuário continuam sendo dele. Ex.: o professor mostra em aula a foto do rosto de um paciente com assimetria, com o termo de autorização assinado; no Instagram, não poderia.", fonte: a(CEO, 'art. 14, III') },

  /* ---------- Publicidade ---------- */
  { t: "nome e número de inscrição do responsável técnico", p: "Porque o paciente e o CRO precisam saber quem responde tecnicamente pelo que a clínica oferece; uma empresa sozinha não tem registro profissional. Com o nome e o número do responsável técnico, dá para conferir se ele é dentista habilitado e cobrar a responsabilidade. O CEO, art. 43, exige isso no anúncio de pessoa jurídica. Ex.: o anúncio de uma clínica de Petrópolis traz o CNPJ, a inscrição no CRO-RJ e 'Responsável técnico: Dr. Fulano, CRO-RJ nº ...'.", fonte: a(CEO, 'art. 43') },
  { t: "Toda publicação leva nome e número de inscrição do profissional", p: "Porque a identificação permite ao público e ao CRO saber quem está falando e conferir se é um profissional habilitado, e torna o autor responsável pelo que publica. A Res. CFO-196/2019, art. 4º, exige isso. Ex.: o post da dentista com a selfie da paciente traz 'Dra. Fulana, CRO-RJ nº ...' na legenda.", fonte: a(R196, 'art. 4º') },
  { t: "Autorização prévia da paciente ou do representante legal", p: "Porque a imagem é um direito da própria pessoa (CF, art. 5º, X), e o rosto e o sorriso dela num post a expõem para sempre. O TCLE prévio mostra que ela entendeu onde a foto vai aparecer e concordou antes da publicação. A Res. CFO-196/2019 (art. 1º) exige essa autorização. Ex.: antes da selfie no dia da entrega das facetas, a dentista pede à paciente que assine o termo de uso de imagem.", fonte: a(R196 + '; ' + CF, 'art. 1º') },
  { t: "sem mostrar equipamentos, instrumentais, materiais ou tecidos biológicos", p: "Porque a selfie é permitida para mostrar a relação com o paciente, não para fazer propaganda sensacionalista do procedimento nem expor sangue, gengiva aberta ou peças com material biológico. A Res. CFO-196/2019, art. 1º, §1º, proíbe essas imagens. Ex.: a dentista pode postar a foto sorrindo ao lado da paciente; não pode postar nas redes sociais a bandeja com o dente extraído e gaze com sangue.", fonte: a(R196, 'art. 1º, §1º') },
  { t: "podem ser divulgadas pelo cirurgião-dentista que fez o procedimento", p: "Porque só quem fez o tratamento pode garantir que as fotos do diagnóstico e da conclusão são verdadeiras e mostrar um trabalho que é dele; divulgar trabalho alheio engana o público. Com o TCLE prévio, a Res. CFO-196/2019 (art. 2º) permite. Ex.: o dentista publica o antes e o depois das próteses que ele mesmo fez, com o termo assinado pelo paciente.", fonte: a(R196, 'art. 2º') },
  { t: "divulgar casos clínicos de autoria de terceiros", p: "Porque mostrar o caso de outro profissional como se fosse seu (ou sem deixar claro de quem é) engana o paciente sobre a capacidade de quem anuncia, e ainda usa a imagem de um paciente que nunca autorizou aquele dentista. A Res. CFO-196/2019, art. 4º, proíbe. Ex.: um dentista não pode repostar nas redes sociais o antes e depois de um caso de outro colega para atrair clientes.", fonte: a(R196, 'art. 4º') },
  { t: "vídeos e imagens do transcurso", p: "Porque mostrar o procedimento em andamento tende ao sensacionalismo (sangue, instrumentos, sofrimento), expõe o paciente num momento vulnerável e transforma o tratamento em espetáculo de marketing. A Res. CFO-196/2019, art. 3º, só permite essas imagens em publicação científica. Ex.: filmar a extração de um siso para um reels é proibido; o mesmo vídeo num artigo científico, com autorização, pode.", fonte: a(R196, 'art. 3º') },
  { t: "proibido mostrar o procedimento em andamento", p: "Porque o paciente no meio do procedimento está vulnerável (anestesiado, de boca aberta, às vezes sangrando), e a imagem vira atração de marketing em vez de informação. A Res. CFO-196/2019 (art. 3º) proíbe, com exceção da publicação científica, onde o objetivo é ensinar. Ex.: um vídeo no TikTok do preparo dos dentes para facetas, ao vivo, é infração.", fonte: a(R196, 'art. 3º') },
  { t: "sensacionalismo, autopromoção e promessa de resultado", p: "Porque essas formas de propaganda exploram a vontade do paciente e criam expectativa que a biologia nem sempre cumpre. A promessa de resultado ainda pode virar prova contra o dentista num processo. A Res. CFO-196/2019 (art. 2º, §1º) proíbe mesmo quando a imagem foi autorizada. Ex.: legenda 'sorriso perfeito garantido em 1 dia' num antes e depois é infração, mesmo com o TCLE assinado.", fonte: a(R196, 'art. 2º, §1º') },
  { t: "anunciar ao público em geral", p: "Porque o técnico em prótese dentária não pode atender o paciente diretamente: a Lei 6.710/1979 (art. 4º, I e III) proíbe prestar assistência direta a clientes e fazer propaganda ao público em geral. O cliente do laboratório é o dentista, que examina, molda e responde pelo tratamento. O CEO, art. 41, §1º, repete a proibição. Ex.: um laboratório de prótese de Petrópolis pode anunciar numa revista para dentistas, mas não impulsionar 'prótese sem precisar de dentista' no Instagram.", fonte: a(L6710 + '; ' + CEO, 'Lei 6.710 art. 4º; CEO art. 41') },
  { t: "não anunciam ao público", p: "Porque o laboratório de prótese não pode ter o paciente como cliente: quem diagnostica, molda, prova e instala é o cirurgião-dentista, e o técnico trabalha a partir do que ele manda. Por isso a propaganda só pode ser dirigida a dentistas, em meio especializado, com responsável técnico e inscrição no CRO (CEO, art. 41, §2º; Lei 6.710/1979, art. 4º). Ex.: o laboratório distribui folheto com a tabela de serviços para os consultórios, nunca para a população.", fonte: a(CEO + '; ' + L6710, 'art. 41') },
  { t: "afixar no laboratório o aviso da restrição", p: "Porque o paciente leigo nem sempre sabe que não pode encomendar prótese direto ao técnico. O aviso do CRO, em lugar visível, informa o público e protege o técnico de ser pressionado a atender. O CEO, art. 41, §3º, exige esse aviso, e a Lei 6.710/1979 (art. 4º, I) proíbe o atendimento direto. Ex.: alguém entra num laboratório pedindo uma dentadura; o aviso na parede mostra que ele precisa passar antes por um dentista.", fonte: a(CEO + '; ' + L6710, 'art. 41, §3º') },
  { t: "alcança técnicos e pessoas jurídicas", p: "Porque o Código de Ética vale para todos os inscritos no Conselho: cirurgiões-dentistas, técnicos e auxiliares, e também as clínicas e laboratórios registrados. Sem isso, uma empresa poderia fazer em nome dela o que o dentista não pode. Ex.: um técnico em prótese dentária inscrito no CRO-RJ que anuncia ao público responde a processo ético, assim como a clínica que publica propaganda irregular.", fonte: a(CEO, 'art. 1º') },
  { t: "para atrair clientela é infração ética", p: "Porque chamar o serviço de 'popular' sugere que a saúde é uma mercadoria barata e atrai o paciente pelo preço, não pela necessidade nem pela qualidade, o que é mercantilização da Odontologia (CEO, art. 9º, XIII). Nessa publicidade, o art. 44, VII, cita a expressão expressamente. Ex.: a placa 'Dentista Popular' na fachada de uma clínica é infração, mesmo que os preços sejam baixos de fato.", fonte: a(CEO, 'arts. 9º, XIII e 44, VII') },
  { t: "na medida da culpa de cada um", p: "Porque quem participa da publicidade irregular contribui para ela de formas diferentes: o dono pagou, o responsável técnico deixou passar, outro profissional emprestou a imagem. O CEO, art. 45, faz todos responderem, mas cada um na proporção do que fez, para a pena ser justa. Ex.: no anúncio 'implante a partir de R$ 99,00' da franquia, o responsável técnico não escapa dizendo que 'quem fez foi o dono'.", fonte: a(CEO, 'art. 45') },
  { t: "propaganda com preços e modalidades de pagamento", p: "Porque anunciar preço faz o paciente escolher o tratamento pelo valor, como se fosse produto de prateleira, sem avaliação clínica; o preço certo depende do exame. Isso é mercantilização da Odontologia, e o CEO, art. 44, I, proíbe. A Res. CFO-271/2025 tirou a restrição a cartão de desconto, mas não liberou o preço na propaganda. Ex.: 'Clareamento por R$ 99,00 em 10x' num outdoor de Petrópolis é infração.", fonte: a(CEO + '; ' + R271, 'art. 44, I') },

  /* ---------- Lesões corporais ---------- */
  { t: "ocupações habituais por mais de 30 dias", p: "Porque a lei usa o tempo de incapacidade como medida da gravidade: uma lesão que tira a pessoa das atividades do dia a dia por mais de 30 dias é mais séria do que uma que se resolve em poucos dias. Por isso o Código Penal, art. 129, §1º, I, a classifica como lesão grave, com pena maior. Ex.: fratura de mandíbula com bloqueio maxilomandibular por 45 dias, em que a vítima não consegue comer nem falar direito.", fonte: a(CP, 'art. 129, §1º, I') },
  { t: "Atividades do dia a dia da pessoa", p: "Porque a lei protege qualquer pessoa, não só quem tem emprego: criança, aposentado e desempregado também podem ficar incapazes. Por isso 'ocupações habituais' (CP, art. 129, §1º, I) inclui comer, falar, estudar e se cuidar, e não só trabalhar. Ex.: um aposentado de Petrópolis que fraturou a mandíbula e ficou 40 dias sem conseguir mastigar teve lesão grave, mesmo sem emprego.", fonte: a(CP, 'art. 129, §1º, I') },
  { t: "logo que decorra o prazo de 30 dias", p: "Porque só depois de passar 30 dias dá para saber se a incapacidade durou MAIS de 30 dias. No primeiro exame, o perito descreve a lesão, mas ainda não sabe quanto tempo a vítima vai ficar incapacitada. O CPP, art. 168, §2º, manda o exame complementar logo depois desse prazo, contado da data do crime. Ex.: vítima de agressão examinada no dia 1º volta ao IML no dia 31 para o perito ver se ainda não consegue mastigar.", fonte: a(CPP, 'art. 168, §2º') },
  { t: "Perda ou inutilização de membro, sentido ou função", p: "Porque perder totalmente uma função é mais grave do que ficar com ela diminuída. Por isso o Código Penal separa: debilidade permanente (perda parcial) é lesão grave, no §1º, III; perda ou inutilização (perda total) é do §2º, III, com pena maior. Ex.: perder alguns dentes costuma ser debilidade da mastigação; perder a capacidade de mastigar por completo seria perda da função.", fonte: a(CP, 'art. 129, §§1º e 2º') },
  { t: "perder alguns dentes pode ser debilidade permanente da mastigação", p: "Porque a mastigação é uma função, e perder alguns dentes a diminui de forma permanente, sem acabar com ela: a pessoa ainda mastiga com os outros dentes, só que pior. Isso é debilidade permanente de função, lesão grave (CP, art. 129, §1º, III). A prótese não apaga a lesão, porque é um recurso artificial. Ex.: vítima que perdeu os dois incisivos centrais num soco: o perito avalia a debilidade da mastigação e da fonação.", fonte: a(CP + '; ' + VAN, 'art. 129, §1º, III') },
  { t: "Nome usado pela doutrina", p: "Porque o Código Penal não usa a palavra 'gravíssima': o §2º do art. 129 só lista os resultados e dá uma pena maior que a do §1º. Os estudiosos do direito (a doutrina) passaram a chamar essas lesões de 'gravíssimas' para diferenciá-las das 'graves'. Ex.: um laudo descreve deformidade permanente no rosto; o advogado e o juiz falam em lesão gravíssima, mas a lei diz só 'se resulta deformidade permanente'.", fonte: a(CP, 'art. 129, §2º') },
  { t: "a classificação final é do juiz", p: "Porque o perito descreve a lesão e responde às perguntas técnicas, mas enquadrar o fato na lei é decisão jurídica. O CPP, art. 182, diz que o juiz não fica preso ao laudo, podendo aceitá-lo ou rejeitá-lo no todo ou em parte. Ex.: o odontolegista descreve uma cicatriz permanente no lábio; é o juiz quem decide se aquilo é deformidade permanente para o Código Penal.", fonte: a(CPP, 'art. 182') },
  { t: "uma alteração estética duradoura e visível", p: "Porque a lei pune a deformidade permanente (CP, art. 129, §2º, IV) pelo prejuízo que ela causa na vida da vítima: aparência, autoestima, relações. Por isso o perito avalia se a alteração é permanente e se é visível, e não só o tamanho. Ex.: cicatriz grande na bochecha depois de uma agressão com caco de vidro é avaliada como possível deformidade permanente.", fonte: a(CP, 'art. 129, §2º, IV') },
  { t: "o artigo mais usado é o 129", p: "Porque a maior parte das perícias da Odontologia Legal no vivo é de agressão física: socos e quedas atingem muito a face e a boca (dentes quebrados, fraturas de mandíbula, cortes no lábio). O art. 129 do Código Penal é o que define a lesão corporal e a classifica pelo resultado. Ex.: depois de uma briga, a vítima faz exame de corpo de delito e o laudo diz se houve debilidade, deformidade ou incapacidade.", fonte: a(CP, 'art. 129') },

  /* ---------- Lei 5.081 e prescrição ---------- */
  { t: "de uso interno e externo, indicadas em Odontologia", p: "Porque o dentista trata doenças da boca que muitas vezes precisam de remédio por via oral (antibiótico, anti-inflamatório, analgésico), e não só de pomada. A Lei 5.081/1966, art. 6º, II, dá essa competência, com o limite de que o medicamento seja indicado em Odontologia. Ex.: depois de drenar um abscesso no 36, o dentista prescreve amoxicilina por via oral.", fonte: a(L5081, 'art. 6º, II') },
  { t: "O limite é a indicação odontológica", p: "Porque a competência do dentista é a boca e as estruturas ligadas a ela; prescrever para doença fora da Odontologia seria agir fora da profissão, o que o CEO também proíbe (art. 11, XIV). A Lei 5.081, art. 6º, II, fala em medicamentos 'indicados em Odontologia'. Ex.: o dentista pode receitar antibiótico para infecção de origem dentária, mas não para infecção urinária do paciente.", fonte: a(L5081, 'art. 6º, II') },
  { t: "no caso de acidentes graves que comprometam a vida", p: "Porque, numa emergência na cadeira, não dá tempo de esperar o médico chegar: o dentista é quem está ali para socorrer. A Lei 5.081, art. 6º, VIII, autoriza prescrever e aplicar medicação de urgência nesses casos, e o CEO dispensa o consentimento prévio em urgência e emergência (art. 11, X). Ex.: paciente com anafilaxia depois de um medicamento recebe adrenalina do dentista enquanto a ambulância é chamada.", fonte: a(L5081, 'art. 6º, VIII') },
  { t: "anexo ao consultório, laboratório de prótese", p: "Porque a prótese faz parte do tratamento odontológico, e o dentista pode querer fazer ou acompanhar o trabalho de laboratório no próprio consultório, assim como ter raios X e equipamento para exames da sua área. A Lei 5.081/1966, art. 6º, VII, permite isso expressamente. Ex.: um dentista de Petrópolis tem um pequeno laboratório de prótese ao lado da sala clínica para ajustar próteses e fazer reparos na hora.", fonte: a(L5081, 'art. 6º, VII') },
  { t: "aplicar anestesia local e troncular", p: "Porque quase todo tratamento odontológico precisa de anestesia, e muitos dentes (como os molares inferiores) só ficam anestesiados com o bloqueio do tronco do nervo. Por isso a Lei 5.081/1966, art. 6º, V, dá ao dentista a competência para as duas. Ex.: para tratar o canal de um molar inferior, o dentista faz o bloqueio do nervo alveolar inferior (anestesia troncular).", fonte: a(L5081, 'art. 6º, V') },
  { t: "veda ao cirurgião-dentista exercer mais de duas especialidades", p: "Porque cada especialidade exige formação longa e prática contínua; o limite impede que alguém se apresente como especialista em tudo e engane o paciente sobre sua real qualificação. A Lei 5.081/1966 traz essa vedação no art. 7º, c. Ex.: um dentista registrado em Prótese e em Implantodontia no CRO não pode se anunciar também como especialista em Ortodontia.", fonte: a(L5081, 'art. 7º, c') },

  /* ---------- LGPD ---------- */
  { t: "por ser dado referente à saúde", p: "Porque dado de saúde, se vazar, pode causar discriminação (no emprego, no seguro, na família) e expor a intimidade. Por isso a LGPD, art. 5º, II, o coloca entre os dados pessoais sensíveis, com regras mais rígidas de uso. Ex.: o prontuário que mostra que o paciente é diabético e usa anticoagulante é dado sensível; a clínica precisa guardar com segurança.", fonte: a(LGPD, 'art. 5º, II') },
  { t: "Tem proteção mais forte", p: "Porque o vazamento ou o mau uso de um dado sensível pode causar dano grave: discriminação, constrangimento, perda de emprego. Por isso a LGPD só permite tratá-lo nas hipóteses do art. 11 (consentimento específico ou casos como a tutela da saúde) e proíbe o compartilhamento para vantagem econômica (§4º). Ex.: a clínica não pode vender a lista dos pacientes com doença periodontal para uma empresa de pasta de dente.", fonte: a(LGPD, 'arts. 5º, II e 11') },
  { t: "Todo prontuário odontológico é dado sensível", p: "Porque o prontuário reúne informação de saúde (anamnese, doenças, remédios, diagnósticos, radiografias), e a LGPD, art. 5º, II, define dado referente à saúde como dado pessoal sensível. A Lei 13.787/2018, art. 1º, manda aplicar a LGPD também ao prontuário digital. Ex.: até a ficha de papel de um paciente que só fez uma limpeza tem anamnese com dados de saúde, e precisa ficar guardada em lugar seguro.", fonte: a(LGPD + '; ' + L13787, 'LGPD art. 5º, II') },
  { t: "manda aplicar a LGPD ao prontuário digital", p: "Porque o prontuário digital concentra muitos dados de saúde num sistema que pode ser invadido, copiado ou compartilhado com facilidade. A Lei 13.787/2018 (art. 1º) diz que a digitalização e a guarda do prontuário seguem ela e também a LGPD, para garantir segurança e direitos do paciente. Ex.: a clínica que usa sistema na nuvem precisa de senha, controle de acesso e contrato com o fornecedor sobre proteção de dados.", fonte: a(L13787 + '; ' + LGPD, 'art. 1º') },
  { t: "Usar o mesmo dado para marketing já não está nessa hipótese", p: "Porque a LGPD exige que o dado seja usado só para a finalidade que justificou a coleta (princípio da finalidade, art. 6º, I). A hipótese do art. 11, II, f, cobre a tutela da saúde, 'exclusivamente' em procedimento de saúde; mandar promoção usando o histórico do paciente é outra finalidade e precisaria de consentimento específico. Ex.: usar a lista de pacientes com prótese para oferecer clareamento por WhatsApp sem autorização fere a LGPD.", fonte: a(LGPD, 'arts. 6º, I e 11, II, f') },
  { t: "SEM um consentimento separado", p: "Porque cuidar da saúde do paciente é impossível sem tratar dados de saúde: o dentista precisa anotar alergias, doenças e remédios para atender com segurança. Exigir um consentimento à parte para isso seria inútil e atrasaria o atendimento. Por isso a LGPD, art. 11, II, f, dispensa o consentimento quando o uso é exclusivamente para tutela da saúde, por profissional de saúde. Ex.: anotar no prontuário que o paciente é hipertenso para escolher o anestésico.", fonte: a(LGPD, 'art. 11, II, f') },
  { t: "até a lista de WhatsApp dos pacientes", p: "Porque nome e telefone já são dado pessoal (informação ligada a pessoa identificada ou identificável, LGPD, art. 5º, I), e saber que alguém é paciente de uma clínica odontológica pode revelar dado de saúde, que é dado pessoal sensível. Por isso a lista de contatos também precisa de cuidado. Ex.: criar um grupo de WhatsApp com todos os pacientes expõe o número e o nome de cada um aos outros, o que fere a LGPD.", fonte: a(LGPD, 'art. 5º, I e II') },
  { t: "são normas diferentes, uma de proteção de dados e outra de ética profissional", p: "Porque a LGPD é lei federal que vale para qualquer empresa ou profissional que trate dados (fiscalizada pela autoridade nacional), e o Código de Ética Odontológica é a norma do Conselho que vale só para os inscritos no CRO. Elas chegam ao mesmo resultado (o paciente tem direito de acesso), mas por caminhos diferentes, e uma não é a razão da outra. Ex.: a clínica que nega a cópia pode responder ao CRO (processo ético) e também na autoridade nacional de proteção de dados.", fonte: a(LGPD + '; ' + CEO, 'LGPD art. 18; CEO art. 18, I') },

  /* ---------- Casos reais (identificação e ossada) ---------- */
  { t: "chegando à identificação com certeza científica razoável", p: "Porque, na época (1985), ainda não havia exame de DNA, e a identificação foi feita pela soma de métodos: antropologia forense (sexo, idade, estatura, ossos) e odontologia (comparação dos dentes com registros), com equipe internacional conferindo. Quando vários métodos independentes concordam, a conclusão fica forte, mas ainda é uma probabilidade. Ex.: na ossada de Embu, os peritos de vários países chegaram ao mesmo nome antes de o DNA existir.", fonte: ECK },
  { t: "o DNA veio como prova INDEPENDENTE para encerrar a controvérsia", p: "Porque, quando uma identificação é contestada, a melhor resposta é um método diferente que não dependa do primeiro. O DNA do fêmur, comparado com o do filho e o da esposa (1992), não usou nada da antropologia nem da odontologia de 1985, e chegou ao mesmo resultado. Ex.: a dúvida sobre a ossada de Embu acabou quando um exame genético, feito anos depois e por outra equipe, confirmou a identificação.", fonte: a(JEF + '; ' + ECK, '') },
  { t: "A identificação ganha força quando métodos diferentes", p: "Porque cada método tem sua margem de erro, mas os erros de métodos independentes não se repetem juntos: se antropologia, odontologia e DNA, cada um por um caminho, chegam à mesma pessoa, a chance de engano fica muito pequena. É a mesma lógica do protocolo DVI da INTERPOL. Ex.: na ossada de Embu, antropologia e odontologia (1985) e depois o DNA (1992) apontaram o mesmo homem.", fonte: a(ECK + '; ' + JEF + '; ' + INT, '') }
  ]);
})();
